package com.sisge.ms.service;
import java.io.*; import java.math.*; import java.time.*; import java.util.*; import org.apache.poi.ss.usermodel.*; import org.apache.poi.xssf.usermodel.XSSFWorkbook; import org.springframework.stereotype.Component; import com.sisge.ms.exception.ApiException; import com.sisge.ms.entity.ImportacionReemplazante;
@Component public class ExcelImportParser {
 private static final List<String> HEADERS=List.of("Reemplazante","CUIL","Categoria","Instr.Legal","Periodo Desde","Periodo Hasta","A pagar","A deuda","Titular","Categoria.1","Licencia Desde","Licencia Hasta","Cantidad dias","Tipo de Licencia");
 public List<ImportacionReemplazante> parse(InputStream in) {
  try(Workbook wb=new XSSFWorkbook(in)){ Sheet s=wb.getNumberOfSheets()==0?null:wb.getSheetAt(0); if(s==null||s.getPhysicalNumberOfRows()<2) throw ApiException.bad("The workbook is empty");
   Row header=s.getRow(s.getFirstRowNum()); Map<String,Integer> cols=new HashMap<>(); for(Cell c:header)cols.put(text(c),c.getColumnIndex()); for(String h:HEADERS)if(!cols.containsKey(h))throw ApiException.bad("Missing required header: "+h);
   List<ImportacionReemplazante> out=new ArrayList<>(); for(int n=header.getRowNum()+1;n<=s.getLastRowNum();n++){Row r=s.getRow(n);if(r==null||blank(r))continue; var x=new ImportacionReemplazante();x.setFilaOrigen(n+1); x.setReemplazante(val(r,cols,"Reemplazante"));x.setCuil(val(r,cols,"CUIL"));x.setCategoriaReemplazante(val(r,cols,"Categoria"));x.setInstrumentoLegal(val(r,cols,"Instr.Legal"));x.setPeriodoDesde(date(r,cols,"Periodo Desde"));x.setPeriodoHasta(date(r,cols,"Periodo Hasta"));x.setAPagar(money(r,cols,"A pagar"));x.setADeuda(money(r,cols,"A deuda"));x.setTitular(val(r,cols,"Titular"));x.setCategoriaTitular(val(r,cols,"Categoria.1"));x.setLicenciaDesde(date(r,cols,"Licencia Desde"));x.setLicenciaHasta(date(r,cols,"Licencia Hasta"));x.setCantidadDias(integer(r,cols,"Cantidad dias"));x.setTipoLicenciaExcel(val(r,cols,"Tipo de Licencia"));x.setErrores(validate(x));out.add(x);} if(out.isEmpty())throw ApiException.bad("The workbook has no data rows"); return out;
  }catch(ApiException e){throw e;}catch(Exception e){throw ApiException.bad("Unreadable .xlsx workbook");}
 }
 public String validate(ImportacionReemplazante x){List<String> e=new ArrayList<>();if(x.getReemplazante()==null||x.getReemplazante().isBlank())e.add("reemplazante:REQUIRED");if(!validCuil(x.getCuil()))e.add("cuil:INVALID");if(x.getPeriodoDesde()==null||x.getPeriodoHasta()==null)e.add("periodo:INVALID_DATE");else if(x.getPeriodoDesde().isAfter(x.getPeriodoHasta()))e.add("periodo:INVALID_RANGE");if(x.getLicenciaDesde()!=null&&x.getLicenciaHasta()!=null&&x.getLicenciaDesde().isAfter(x.getLicenciaHasta()))e.add("licencia:INVALID_RANGE");if(x.getCantidadDias()!=null&&x.getCantidadDias()<0)e.add("cantidadDias:INVALID");return String.join(";",e);}
 private String val(Row r,Map<String,Integer> c,String h){Cell x=r.getCell(c.get(h),Row.MissingCellPolicy.RETURN_BLANK_AS_NULL);return x==null?null:text(x);}
 private String text(Cell c){if(c==null)return ""; DataFormatter f=new DataFormatter();return f.formatCellValue(c).trim();}
 private boolean blank(Row r){for(Cell c:r)if(!text(c).isBlank())return false;return true;}
 private LocalDate date(Row r,Map<String,Integer> c,String h){Cell x=r.getCell(c.get(h),Row.MissingCellPolicy.RETURN_BLANK_AS_NULL);if(x==null||text(x).isBlank())return null;try{if(x.getCellType()==CellType.NUMERIC&&DateUtil.isCellDateFormatted(x))return x.getLocalDateTimeCellValue().toLocalDate();if(x.getCellType()==CellType.NUMERIC)return DateUtil.getLocalDateTime(x.getNumericCellValue()).toLocalDate();String v=text(x);try{return LocalDate.parse(v);}catch(Exception ignored){return LocalDate.parse(v,java.time.format.DateTimeFormatter.ofPattern("d/M/uuuu"));}}catch(Exception e){return null;}}
 private BigDecimal money(Row r,Map<String,Integer> c,String h){String s=val(r,c,h);if(s==null||s.isBlank())return null;try{String v=s.replaceAll("[^0-9,.-]","");int comma=v.lastIndexOf(','),dot=v.lastIndexOf('.');if(comma>=0&&dot>=0){if(comma>dot)v=v.replace(".","").replace(",",".");else v=v.replace(",","");}else if(comma>=0)v=v.replace(",",".");else if(dot>=0&&v.length()-dot-1!=2)v=v.replace(".","");return new BigDecimal(v);}catch(Exception e){return null;}}
 private Integer integer(Row r,Map<String,Integer> c,String h){String s=val(r,c,h);try{return s==null||s.isBlank()?null:new BigDecimal(s.replace(",","." )).intValueExact();}catch(Exception e){return null;}}
 private boolean validCuil(String value){if(value==null)return false;String c=value.replaceAll("\\D","");if(!c.matches("\\d{11}"))return false;int[] w={5,4,3,2,7,6,5,4,3,2};int total=0;for(int i=0;i<10;i++)total+=(c.charAt(i)-'0')*w[i];int check=11-(total%11);if(check==11)check=0;else if(check==10)check=9;return check==c.charAt(10)-'0';}
}
